        "body": [
          "昔者，黄帝将甲子分轻重而配成六十，号曰花甲子，其花字诚为奥妙，圣人借意而喻之，不可着意执泥。夫自子至亥十二宫，各有金、木、水、火、土之属，始起于子为一阳，终于亥为六阴，其五行所属金、木、水、火、土，在天为五星，于地为五岳，于德为五常，于人为五脏，其于命也为五行。是故甲子之属乃应之于命，命则一世之事。故甲子纳音象，圣人喻之，亦如人一世之事也。何言乎？子丑二位，阴阳始孕，人在胞胎，物藏根，未有涯际；寅卯二位，阴阳渐开，人渐生长，物以拆甲，群葩渐剖，如人将有立身也；辰巳二位，阴阳气盛，物当华秀，如人三十、四十而有立身之地，始有进取之象；午未二位，阴阳彰露，物已成齐，人至五十、六十，富贵贫贱可知，凡百兴衰可见；申酉二位，阴阳肃杀，物已收成，人已龟缩，各得其静矣；戌亥二位，阴阳闭塞，物气归根，人当休息，各有归着。详此十有二位先后，六十甲子可以次第而晓。",
          "甲子乙丑何以取象为海中之金？盖气在包藏，有名无形，犹人之在母腹也；壬寅癸卯绝地存金，气尚柔弱，薄若缯缟，故曰金泊金；庚辰辛巳以金居火土之地，气已发生，金尚在矿，寄形生养之乡，受西方之正色，乃曰白蜡金；甲午乙未则气已成，物质自坚实，混于沙而别于沙，居于火而炼于火，乃曰沙中金也；壬申癸酉气盛物极，当施收敛之功，颖脱锋锐之刃。盖申酉金之正位，干值壬癸，金水淬砺，故取象剑锋而金之功用极矣；至戌亥则金气藏伏，形体已残，锻炼首饰，已成其状，藏之闺阁，无所施为，而金之功用毕，故曰庚戌辛亥钗钏金。壬子癸丑何以取象桑柘木？盖气居盘屈，形状未伸，居于水地，蚕衰之月，桑柘受气，取其时之生也；庚寅辛卯则气已乘阳，得栽培之势力其为状也，奈居金下，凡金与霜素坚，木居下得其旺，岁寒后凋，取其性之坚也，故曰松柏木；戊辰己巳则气不成量，物已及时，枝叶茂盛，郁然成林，取其木之盛也，故曰大林木；壬午癸未，木至午而死，至未而墓，故杨柳盛夏叶凋，枝干微弱，取其性之柔也，故曰杨柳木；庚申辛酉，五行属金而纳音属木，以相克取之。盖木性辛者，唯石榴木；申酉气归静肃，物渐成实，木居金地，其味成辛，故曰石榴木；观他木至午而死，惟此木至午而旺，取其性之偏也。戊戌己亥，气归藏伏，阴阳闭塞，木气归根，伏乎土中，故曰平地木也。丙子丁丑何以取象涧下水？盖气未通济，高段非水流之所，卑湿乃水就之乡，由地中行，故曰涧下水；甲寅乙卯，气出阳明，水势恃源，东流滔注，其势浸大，故曰大溪水；壬辰癸巳，势极东南，气傍离宫，火明势盛，水得归库，盈科后进，乃曰长流水也；丙午丁未，气当升降，在高明火位，有水沛然作霖，以济火中之水，惟天上乃有，故曰天河水；甲申乙酉，气息安静，子母同位，出而不穷，汲而不竭，乃曰井泉水；壬戌癸亥，天门之地，气归闭塞，水历遍而不趋，势归乎宁谧之位，来之不穷，纳之不溢，乃曰大海水也。戊子己丑何以取象霹雳火？盖气在一阳，形居水位，水中之火，非神龙则无，故曰霹雳火；丙寅丁卯，气渐发辉，因薪而显，阴阳为治，天地为炉，乃曰炉中火也；甲辰乙巳，气形盛地，势定高冈，传明继晦，子母相承，乃曰覆灯火也；戊午己未，气过阳宫，重离相会，炳灵交光，发辉炎上，乃曰天上火也；丙申丁酉，气息形藏，势力韬光，龟缩兑位，力微体弱，明不及远，乃曰山下火也；甲戌乙亥谓之山头火者，山乃藏形，头乃投光，内明外暗，隐而不显，飞光投干，归于休息之中，故曰山头火也。庚子辛丑何以取象壁上土？气居闭塞，物尚包藏，掩形遮体，内外不交，故曰壁上土；戊寅己卯，气能成物，功以育物，发乎根，壮乎萼蕊，乃曰城头土也；丙辰丁巳，气以承阳，发生已过，成齐未来，乃曰沙中土也；庚午辛未，气当承形，物以路彰，有形可质，有物可彰，乃曰路傍土也；戊申己酉，气以归息，物当收敛，龟缩退闲，美而无事，乃曰大驿土也；丙戌丁亥，气成物府，事以美圆，阴阳历遍，势得其间，乃曰屋上土也。",
          "余见路旁之土播殖百谷，午未之地，其盛夏长养之时乎？大驿之土通达四方，申酉之地，其得朋利亨之理乎？城头之土取堤防之功，五公恃之，立国而卫民也；壁上之土明粉饰之用，臣庶资之，爰居而爰处也；沙中之土，土之最润者也，土润则生，故成齐未来而有用；屋上之土，土之成功者也，成功者静，故止于一定而不迁。盖居五行之中，行负载之令，主养育之权，三才五行皆不可失；处高下而得位，居四季而有功。金得之锋锐雄刚，火得之光明照耀，木得之英华越秀，水得之滥波不泛，土得之稼穑愈丰。聚之不散，必能为山，山者，高也；散之不聚，必能为地，地者，原也。用之无穷，生之罔极，土之功用大矣哉！五行取象，皆以对待而分阴阳，即始终而明变化。如甲子乙丑对甲午乙未，海中沙中，水土之辨，阴阳之分也；壬寅癸卯对壬申癸酉，金泊剑锋，金木之辨，刚柔之别也；庚辰辛已对庚戌辛亥，白蜡钗钏，干巽异方，形色各尽也；壬子癸酉对壬午癸未，桑柘杨柳，一曲一柔，形质多别也；庚寅辛卯对庚申辛酉，松柏石榴，一坚一辛，性味迥异也；戊辰己巳对戊戌己亥，大林平地，一盛一衰，巽干殊方也；戊子己丑对戊午己未，霹雳天上，雷霆挥鞭，日月同照也；丙寅丁卯对丙申丁酉，炉中山下，火盛木焚，金旺火灭也；甲辰乙巳对甲戌乙亥，覆灯山头，含光畏风，投光止艮也；庚子辛丑对庚午辛未，壁上路旁，形分聚散，类别死生也；戊寅己卯对戊申己酉，城头大驿，东南西北，坤艮正位也；丙辰丁巳对丙戌丁亥，沙中屋上，干湿互用，变化始终也。",
          "圆看方看，不外旺相死休；因近取远，莫逃金木水火土。以干支而分配五行，论阴阳而大明终始。天成人力相兼，生旺死绝并类。呜呼！六十甲子圣人不过借其象以明其理，而五行性情、材质、形色、功用无不曲尽而造化无余蕴矣。",
          "释六十甲子性质吉凶"
        ],
