          "壬戌，偏库之水，癸亥，临官之水，名曰大海水。盖支干、纳音皆水，忌见群水，虽壬辰水库亦不能当。不忌他土，死绝则吉，生旺则泛滥无所归也。《玉宵宝鉴》云：“亥子，水之正位，壬戌气伏而不顺，唯此水、土损益之，乃成大器。癸亥具纯阳之数，内体至仁，禀之者天资夷旷，志气浩然，发为功案，利泽日时，带煞则凶狡之流。”又曰：丙戌之土为福隆厚，火锺于此故也。己未、庚辰、戊辰、丁丑与此同义。己未，火也，未中有墓木；庚辰，金也，辰中有墓土；戊辰，木也，辰中有墓水；丁丑，水也，丑中有墓金，皆父母之气，各有所养。此五者福壮厚以上，有鬼所伤，不为害，气成故也。",
          "乙巳、戊午，乃盛炎之火。秋冬作德吉，春夏作刑凶。若仲夏暴炎一发，旋即归燥竟焚，和而为咎。乙巳，临官之火，上有一木生之，其气盛矣；戊午，自旺之火，若生秋冬，为温燠之气，为济物之德。若生春夏，旺火复得阳位则作凶，生仲夏，为暴戾、刻忍、凶夭之流也。"
