        "sourceFile": "十本经典四柱古籍/三命通会/《三命通会》-明-万民英.txt",
        "body": [
          "[丙午丁未天河水]",
          "天河水者，乱洒六野，密沛千郊，淋淋泻下银河，细细飞来碧落，此乃天上雨露，发生万物，无不赖之。银河之水，土不能克，故见土不忌，而且有滋润之益；天上之水，地金难生，故见金难益，而亦有涵秀之情；生旺太过则为淫潦，反伤于物，死绝太多则为旱干，又不能生物，要生三秋得时为贵也。水喜长流、大海，内丙午宜癸巳、癸亥，丁未宜壬辰、壬戌，阴阳互见，尤吉；大溪乙卯为雷，井泉己酉为贵，俱以吉论。火喜霹雳，为神龙之火，与此水相济。而倏忽变化，云行雨施，岂有不贵？炉中火旺，大海水旺，如柱中得二火二水，上下上相济，谓之精神俱足，大贵格也；灯头有风，山头有贵，皆以吉论，又须以别水济之方吉；天上就位相克，则忌见之。木石榴、杨柳俱吉，大林有巽，平地有亥，亦吉；松柏、石榴遇丙辛合化，亦以吉论。妙选有灵槎入天河格，是取死绝无根之木，柱无土培则漂流天河是也。土虽不能克，而柱逢庚午辛未，就位相克，土壅水滞，或水又冬生，则水结池塘，必主浊滥；余土如砂中、屋上皆吉，城头，大驿无用，壁上对冲，亦坏造化。水、金虽不能生，独辛亥钗金却属干天，水在天上，只此最吉；余金亦取天干有庚辛、壬癸者为用，甲乙无益，再以禄马贵人参之始得。妙选又以水生人得庚子、壬子为云腾雨施，生春则旱，夏则潦，冬则寒，独三秋最吉；遇甲辰乙巳、庚辰辛巳，柱中有壬为云，有辰为龙，为风雨作霖；若生冬月，是为霜凝薄露，日时喜遇寅卯温和之气，可解斯冻，俱贵格也。",
          "[甲申乙酉井泉水]",
          "井泉水者，寒泉清冽，取养不穷，八家凿之以同饮，万民资之以生活。此水生于金而出于木，故喜见金为福，砂中有土，性与之最宜，钗钏清秀次之，蜡金与钗金相冲，故不宜再见；剑锋申酉太旺，恐有泛滥之灾；海金无取，乙丑为艮，山下出泉，亦吉。此非木不能出，譬之桶论，故见木皆吉，如见平地、大林，须假剑金削之，方可取用；桑拓、杨柳无用；松柏则互换归禄，此其最吉。诸火阴阳互见则吉，霹雳名为入圣，太阳号为显照，二火相见最吉，但不宜并有则凶。诸土路旁、砂中最吉，屋上有天门生水之源，亦吉；城头，壁上与此水则无干涉；大驿就位相克，水为土掩则井不食，须有木去之方可。水喜大海，为引凡入圣；天上、涧下、长流亦不为在灾；大溪甲寅乙卯为吉，如甲申见乙酉，乙酉见甲申，官星互换，最吉；如二水在年时，二木在月日，谓之水绕花堤，乃贵格也。",
          "[壬戌癸亥大海水]",
          "大海水者，总纳百川，汪洋无际，包括乾坤之大，升沈日月之光。此水原有清浊，以两般分论：壬戌有土气为浊，癸亥干支纯水而纳音又水，故清。壬戌人嫌山，以土气太盛，有金清之方吉，癸亥最喜见山，然后海水之性始安；涧下丁丑为山，天河与海上下相通，柱中有木为槎则乘槎入于天河，极为上格；长流、大溪等水毕竟皆归于海，以海水不择细流，故能成其大也；壬辰为龙归大海，尤吉，中间又分阴阳互见，干支合化方可；井泉则有所制，与海不通，故不喜见之。诸金独海中第一，以壬戌癸亥喜见甲子乙丑；砂中亦得，余金又当以贵人禄马参之。火喜天上，与海水相为照耀，最吉；霹雳己丑为山，戊癸合化，柱得木火旺地，亦吉；山下、山头、覆灯诸火不宜见。木唯壬子癸丑、壬午癸未俱吉；大林有风冲动，水性不安；平地厚载，则就位相得；松柏、石榴若无土制则漂泊无定。土爱路旁、大驿，唯此二土足以振之不泄，况癸亥见戊申为天关地轴大格，日时遇此厚土，纵有风雷，亦不为害；城头己卯须资艮则吉，如逢霹雳，则雷火变化，海水汹涌，亦主贫寒。六十甲子纳金取象，其十干有可以为金，有不可以为金者，虽因所值之数不同而五行类化类从之妙，其理亦不可不知。如甲乙、庚辛、壬癸，此三行者可以为金，而丙丁、戊己不与焉；庚辛原金，固为本家之物，壬癸非金也，又胡为金？此金水相生之理，而水亦可以为金，故世有水碧金明之物；甲乙之木，其质坚强，世有木化为石者，可以例见，故此二者可以取象为金，与本家之物同也。丙丁属火，燥刚不同，戊己属土，柔刚不同，与金相反，自不可以金论。戊己庚辛壬癸此六干者可以为木，而甲乙丙丁不预焉。以丙丁原火，所以焚木，自不可取；甲乙原木，胡不取之？殊不知五行中金还金，水还水，火还火，土还土，独木则变，以木资火、水、土之性，假合而生，脉绝而枯槁则还水也，灼之为火则还火也，腐之为土则还土也。故不用木，所以脱体而化神也。六甲轮环，所值之数，五行错综，所得之理，自可以默识矣。凡木皆水所生，其津液即水也，故壬癸可以为木，庚辛之质，其坚与甲乙同，故甲乙可以为金，而庚辛可以为木，互换交通，其理亦无二也。丙丁、甲乙、壬癸取象为水，以壬癸原水也，丙丁其化也，甲乙之津液即为水也；戊己之土所以克水，庚辛之金所以燥水，气有异也，自不可以水论。甲乙、丙丁、戊己取象为火，以丙丁原火也，戊己其化也，甲乙之生燃即火也，壬癸之水所以克火，庚辛之金所以燥火，类不同也，自不可以火论。丙丁、戊己、庚辛纳音属土，戊己原土也，丙丁之火化而为灰，灰即土也，庚辛之金混于土中，乃土之精气所结，故皆可以为土。若壬癸之水润下不凝，甲乙之木散上不止，自不可以土论。究其取象，有轻重，有大小，有刚柔，有气味，有体质，有功用，各各不同，此又兼地支方隅之位，旺相休囚不同，而干天之所值或从本象，或从化象，或从别象，天人交尽，其理生克，互成其义，此金所以有海中、砂中、金泊、白蜡、剑锋、钗钏之别，而金之象无余蕴矣，余木、火、水、土可以例见。此纳音取象所以为造化之妙也与！"
        ],
