          "夫一气浑沦，形质未离，熟为阴阳？太始既肇，裂一为三，倏息乃分，天得之而轻清为阳，地得之而重浊为阴，人位乎天 地之中，禀阳阴冲和之气。故此轻清者为十干，主禄，谓之天元，重浊者为十二支，主身，谓之地元，天地多正其位，成才于两间者，乃所谓人也。故支吕所藏者主命，谓之人元，名为司事之神，以命术言之为月令。如正月建寅，寅中有艮土用事五日，丙火长生五日，甲木二十日；二月建卯，卯中有甲木用事七日，乙木二十三日；三月建辰，辰中有乙木用事七日，壬水墓库五日，戊土一十八日；四月建已，已中有戊土七日，庚金长生五日，丙火一十八日；五月建午，午中丙火用事七日，丁火二十三日；六月建未，未中有丁火用事七日，甲木墓库五日，已土一十八日；七月建申，申中有坤土用事五日，壬水长生五日，庚金二十日；八月建酉，酉中有庚金用事七日，辛金二十三日；九月建戌，戌中有辛金用事七日，丙火墓库五日，戊土一十八日；十月建亥，亥中有戊土五日，甲木长生五日，壬水用事二十日；十一月建子，子中有壬水用事七日，癸水二十三日；十二月建丑，丑中有癸水用事七日，庚金墓库五日，已土一十八日。此十二支按十二月各藏五行为人元，以配四时则春暖秋凉冬寒夏热，如环无端，终而复始，岁功毕而成一年。"
