          "凡论人命，年月日时排成四柱，遁月从年，则以年为本，遁时从日，则以日为主。古法以年看，子平以日看，本此。如人本木而得卯月以乘之，主金而得酉时以乘子，谓之本，主乘旺气；如本水而得甲申、丙子、壬戌、癸亥月；主火而得丙寅、戊午、甲辰、乙已时；本木而得己亥、辛卯、甲寅、庚寅月，主金而得辛已、癸酉、庚申、壬申时，谓之本，主还家； 本木而得癸未月，主金而得乙丑时；木水而得壬辰月，主火而得甲戌时，谓之本，主持印。四位如此，更吉神往来，凶煞回避，谓之本主得位，本胜于主者多得祖荫，主胜于本者当自卓立，本主两强，富贵双全。四柱中更抑扬归中，无太过不及，方作好命，有一位不及，必主蹇滞，然诸家命术皆云好年不如好月，好月不如好日，好日不如好时，大率以年则统乎一岁，月则该乎三十，而时日为得之。独不知得日时之吉而月不应，反为无用，况用神多取诸月，是月又可轻乎？唐李虚中独以日干为主，却以年月时合看生克制化，旺相休囚，取立格局。此发前贤所未发，故今术家宗之。",
          "又曰年为太岁，主人一生祸福，如当生太岁，是金是木，要日月相生相应，造化和顺，则根基牢固，一生卓立成就。众支干五行不顺反克，冲破为伤，本主无寿，被形带煞。及生，月日时者主损木气，破伤祖业，六亲冷淡蹇滞之命也。月为运 元，行运从月逮起，若日时是本生年之福，宜归运元生旺处以扶助之，故官印贵人，禄马财星宜在运元生旺处为佳；若日时是本生年之祸，宜归运元剥克处以潜济之。故土多窒塞，宜归运元疏通处；水多泛滥，宜归运元归宿处；火多暴露，宜归运元晦息处；金木太强，宜归运元沈潜处。或运元集生时之福，或运元发福于生时，日者三阳之会，帝皇之象，时者近侍之臣，以亲帝座，而时日有君臣庆会，天地德合。或年月日时四位纳音生旺之气，或四位禄与福贵气聚于时上，谓之四位集福于帝座；或时倒揭，旺气秀气散在诸位，而诸位乘吉会之气者，谓之帝座发福于四位。夫集福于帝座则以纯厚忠信为心，发福于四位则以聪明端直自进。若近侍之臣切忌土火金气太旺，不能久住，水木清奇多是翰林。年月发福处，不要生时破坏，败坏处仍要生时解释。",
