          "夫德者，利物济人、掩凶作善之谓也。天德者，谓周天有三百六十五度二十五分半，除十二宫分野，每宫各占三十度，共计三百六十度，外有五度二十五分半，散在十二佐宫甲、庚、丙、壬、乙、辛、丁、癸、干、坤、艮、巽，谓之神藏煞没。每宫各得四十四分，所以子午卯酉中有甲庚丙壬，辰戌丑未中有乙辛丁癸，寅申巳亥中有乾坤艮巽，此十二位宫，能回凶作善，乃曰天德也。月德者，乃三合所照之方，日月会合之辰，申子辰会酉出，庚入垣于壬；亥卯未会干出，丙入垣于甲；午戌会卯出，甲入垣于丙；巳酉丑会子出，壬入垣于庚，故壬甲丙癸谓之月德，而辰未戌丑四月，天德亦同属焉。盖日月照临之宫，凡天曜地煞，尽可制服，故可回凶作吉。阎东叟云：贵神在位，诸煞伏藏；二德扶持，众凶解散。凡命中带凶煞，得此二德扶化，凶不为甚；须要日上见，时上不犯克冲刑破，方吉。凡人得之，一生安逸，不犯刑，不逢盗，纵遇凶祸，自然消散。与三奇、天乙贵同并，尤为吉庆。或财官、印绶、食神、变德，各随所变，更加一倍之福。入贵格，主登科甲，得君宠任；或承祖荫，亦得显达。入贱格，一生温饱，福寿两全；纵有蹇滞，亦能守分固穷，不失为君子。女命得之，多为贵人之妻。《三命铃》云：天德者，五行福德之辰，若人遇之，主登台辅之位，更有月德并者，尤好；纵有凶煞，亦主清显。《子平赋》云：“印绶得同天德，官刑不犯，至老无殃”。是天德胜月德也。",
