          "庚金属阳，乃金银铜铁之类，禀太阳而成。要见丁火制之，方能成器。如见丙火，遇而不遇。喜行东南火木之运，明亮，金得制。如值寅卯临于甲乙，及己午未官星印元得气之乡，皆是发越。惟居西北方，为金沈水底，是不能成器。",
