          "鬼谷要诀云：甲庚丙壬相逐来，支神次第又相该；更兼禄马居生旺，为官必是到三台。又云：乙辛丁癸顺挑连，五行生旺禄兼全，更秉旺气临官上，宰相公侯在此迁。又鬼谷遗文云：罡中是乙，魁裡伏辛，鬼神得癸，小吉隐丁。<注云：辰中是乙，戊中是辛，丑为贵神，未为小吉，丑中有贵，未中有丁。>",
