          "莫能外此也。",
          "阳主聚，以进为进，故主顺；阴主散，以退为退，故主逆。此生沐浴等项，",
          "所以有阳顺阴逆之殊也。四时之运，功成者去，等用者进，故每流行于十二支之",
          "月，而生旺墓绝，又有一定。阳之所生，即阴之所死，彼此互换，自然之运也。",
