          "道有体用，不可以一端论也，要在扶之抑之得其宜。",
          "原注：有以日主为体，提纲为用。日主旺，则提纲之食神财官皆为我",
          "用：日主弱，则提纲有物，帮身以制其神者，亦皆为我用。提纳为体，",
          "喜神为用者，日主不能用乎提纲矣。提纲食伤财官太旺，则取年月时上",
          "印比为喜神；提纲印比太旺，则取年月时上食伤财官为喜神而用之。此",
          "二者，乃体用之正法也。有以四柱为体，有以化神为体，四柱为用，化",
          "之真者，即以化神为体，以四柱中与化神相生相克者，取以为用。有以",
          "四柱为体，岁运为用，有以喜神为体，辅喜神之神为用，所喜之神，不",
          "能自用以为体用辅喜之神。有以格象为体，日主为用者，须八格气象，",
          "及暗神，化神，忌神，客神，皆成一体段。若是一面格象，与日主无干",
          "者，或伤克日主太过，或帮扶日主太过，中间要寻体用分辨处，又无形",
          "迹，只得用日主自去引生喜神，别求一个活路为用矣。有以日主为用，",
