          "美亦过度矣。有用立而体行者，有体立而用行者，正体用之理也。如用",
          "神不行于流行之地，且又行助体之运财不妙。有体用各立者，体用皆",
          "旺，不分胜负，行运又无轻重上下，则各立。有体用俱滞者，如木火俱",
